const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * `android/` is generated by prebuild and gitignored, so the release signing config cannot live
 * there. `expo prebuild` deletes and recreates `app/build.gradle`, so a committed patch would be
 * lost on every rebuild.
 *
 * This plugin folds the release signing config into the generated file instead. Secrets are never
 * written into the Gradle file: it reads them from the environment at configure time, which is what
 * GitHub Actions provides from repository secrets.
 *
 * When KEYSTORE_FILE is absent (a plain local build), release keeps falling back to the debug
 * keystore so `assembleRelease` still works on a developer machine.
 */

const MARKER = '// @generated pocket-ledger release signing';

const RELEASE_BLOCK = `        ${MARKER}
        release {
            storeFile file(System.getenv("KEYSTORE_FILE") ?: "release.keystore")
            storePassword System.getenv("KEYSTORE_PASSWORD")
            keyAlias System.getenv("KEY_ALIAS")
            keyPassword System.getenv("KEY_PASSWORD")
        }
`;

const DEBUG_SIGNING = 'signingConfig signingConfigs.debug';
const RELEASE_SIGNING = 'signingConfig (System.getenv("KEYSTORE_FILE") ? signingConfigs.release : signingConfigs.debug)';

function fail(reason) {
  throw new Error(`withReleaseSigning: ${reason}. The Expo Android template changed; update the plugin.`);
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    const gradle = cfg.modResults.contents;
    if (gradle.includes(MARKER)) return cfg;

    const signingConfigsAt = gradle.indexOf('signingConfigs {');
    if (signingConfigsAt < 0) fail('no signingConfigs block in app/build.gradle');

    // Insert as the first entry of the block, right after its opening brace line.
    const afterOpen = gradle.indexOf('\n', signingConfigsAt) + 1;
    let next = gradle.slice(0, afterOpen) + RELEASE_BLOCK + gradle.slice(afterOpen);

    // Only the release buildType should switch; debug keeps the debug keystore.
    const buildTypesAt = next.indexOf('buildTypes {');
    if (buildTypesAt < 0) fail('no buildTypes block in app/build.gradle');
    const releaseAt = next.indexOf('release {', buildTypesAt);
    if (releaseAt < 0) fail('no release buildType in app/build.gradle');

    const debugAt = next.indexOf(DEBUG_SIGNING, releaseAt);
    if (debugAt < 0) fail('release buildType does not use the debug signing config');

    next = next.slice(0, debugAt) + RELEASE_SIGNING + next.slice(debugAt + DEBUG_SIGNING.length);

    cfg.modResults.contents = next;
    return cfg;
  });
};
